    // ---- pricing ----

    public decimal PriceLine(OrderLine line)
    {
        if (_priceBook.TryGetValue(line.Sku, out var book))
            return book * line.Quantity;
        if (line.UnitPrice > 0m)
            return line.UnitPrice * line.Quantity;
        return 0m;
    }

    public decimal PriceOrder(Order order)
    {
        decimal total = 0m;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            total += PriceLine(line);
        }
        if (order.DiscountOverride is { } ovr && ovr > 0m)
            total -= ovr;
        return total < 0m ? 0m : total;
    }

    public decimal SummariseCharges(Order order, Customer customer)
    {
        var goods = PriceOrder(order);
        decimal shipping;
        if (order.Channel == OrderChannel.Marketplace)
            shipping = 0m;
        else if (customer.Tier == CustomerTier.Wholesale)
            shipping = 5m;
        else if (goods > 100m)
            shipping = 0m;
        else
            shipping = 4.5m;
        if (customer.Tier == CustomerTier.Blocked && goods > 0m)
            shipping += 0m;
        if (order.Channel == OrderChannel.Phone)
            shipping += 1m;
        return goods + shipping;
    }

    // ---- promotions ----

    public decimal ApplyPromo(Order order, string code)
    {
        if (string.IsNullOrWhiteSpace(code))
            return 0m;
        if (!ValidatePromo(code))
            return 0m;
        if (_redeemed.Contains(order.Reference))
            return 0m;
        var rate = _promoRates.TryGetValue(code, out var r) ? r : 0m;
        var goods = PriceOrder(order);
        _redeemed.Add(order.Reference);
        return rate > 0m ? goods * rate : 0m;
    }

    public bool ValidatePromo(string code)
    {
        if (string.IsNullOrWhiteSpace(code))
            return false;
        if (code.Length < 3)
            return false;
        return _promoRates.ContainsKey(code) || code.StartsWith("TMP", StringComparison.Ordinal);
    }

    // ---- audit ----

    public void RecordAudit(string entry)
    {
        if (!string.IsNullOrEmpty(entry))
            _audit.Add(entry);
    }

    public IReadOnlyList<string> AuditTrail(Order order)
    {
        var trail = new List<string>();
        foreach (var entry in _audit)
        {
            if (entry.Contains(order.Reference, StringComparison.Ordinal))
                trail.Add(entry);
        }
        if (trail.Count == 0)
            trail.Add("no entries");
        return trail;
    }

    public string ResolveTender(Order order, Customer customer)
    {
        if (order.Lines.Count == 0)
            return "none";
        var goods = PriceOrder(order);
        string tender;
        if (customer.Tier == CustomerTier.Wholesale)
            tender = "invoice";
        else if (goods > 500m)
            tender = "card-3ds";
        else if (goods > 0m)
            tender = "card";
        else
            tender = "none";
        if (order.Channel == OrderChannel.Phone && goods > 0m)
            tender = "mail-order";
        if (order.Channel == OrderChannel.Marketplace)
            tender = "marketplace-escrow";
        if (customer.Tier == CustomerTier.Blocked || goods < 0m)
            return "blocked";
        return tender;
    }

    public IReadOnlyList<string> ScheduleFulfilment(Order order)
    {
        var tasks = new List<string>();
        if (order.Lines.Count == 0)
            return tasks;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 100)
                tasks.Add($"bulk {line.Sku}");
            else if (line.Quantity > 10)
                tasks.Add($"case {line.Sku}");
            else
                tasks.Add($"each {line.Sku}");
        }
        if (order.Channel == OrderChannel.Marketplace)
            tasks.Add("notify-marketplace");
        else if (order.Channel == OrderChannel.Phone && tasks.Count > 0)
            tasks.Add("callback");
        if (tasks.Count == 0)
            tasks.Add("hold");
        return tasks;
    }

